    N = int(data[0])
    L = floor_cuberoot(N)
    isqrt = math.isqrt

    for d in range(1, L + 1):
        if N % d != 0:
            continue

        q = N // d
        d2 = d * d
        D = 12 * q - 3 * d2

        if D < 0:
            continue

        s = isqrt(D)
        if s * s != D:
            continue

        t = s - 3 * d
        if t > 0 and t % 6 == 0:
            y = t // 6
            x = y + d
            print(x, y)
            return

    print(-1)


