class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        N = n + m - 1

        pat = [ord(ch) - 97 for ch in str2]

        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and pat[i] != pat[j]:
                j = pi[j - 1]
            if pat[i] == pat[j]:
                j += 1
            pi[i] = j

        c_range = range(26)
        trans = [[0] * 26 for _ in range(m + 1)]
        for q in range(m + 1):
            match = pat[q] if q < m else -1
            fallback = pi[q - 1] if q > 0 else 0
            for c in c_range:
                if q < m and c == match:
                    trans[q][c] = q + 1
                elif q == 0:
                    trans[q][c] = 0
                else:
                    trans[q][c] = trans[fallback][c]

        bits = [1 << i for i in range(m + 1)]
        mask_none = [0] * (m + 1)
        mask_T = [0] * (m + 1)
        mask_F = [0] * (m + 1)
        for q in range(m + 1):
            mn = mt = mf = 0
            for c in c_range:
                ns = trans[q][c]
                b = bits[ns]
                mn |= b
                if ns == m:
                    mt |= b
                else:
                    mf |= b
            mask_none[q] = mn
            mask_T[q] = mt
            mask_F[q] = mf

        req = [0] * N
        for i, ch in enumerate(str1):
            req[i + m - 1] = 1 if ch == 'T' else 2

        all_states = (1 << (m + 1)) - 1
        dp = [0] * (N + 1)
        dp[N] = all_states
        mp1 = m + 1
        q_range = range(mp1)
        masks_by_req = (mask_none, mask_T, mask_F)

        for p in range(N - 1, -1, -1):
            masks = masks_by_req[req[p]]
            nxt = dp[p + 1]
            cur = 0
            for q in q_range:
                if masks[q] & nxt:
                    cur |= bits[q]
            if cur == 0:
                return ""
            dp[p] = cur

        if not (dp[0] & 1):
            return ""

        letters = [chr(97 + i) for i in c_range]
        ans = [''] * N
        state = 0
        for p in range(N):
            r = req[p]
            nxt = dp[p + 1]
            row = trans[state]
            for c in c_range:
                ns = row[c]
                if r == 1:
                    if ns != m:
                        continue
                elif r == 2:
                    if ns == m:
                        continue
                if nxt & bits[ns]:
                    ans[p] = letters[c]
                    state = ns
                    break
            else:
                return ""
        return ''.join(ans)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**15 + 1

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(CAP, fact[i - 1] * i)

        def ways(rem_odd: int, rem_even: int, next_odd: bool) -> int:
            if rem_odd < 0 or rem_even < 0:
                return 0

            m = rem_odd + rem_even
            if m == 0:
                return 1

            if next_odd:
                need_odd = (m + 1) // 2
                need_even = m // 2
            else:
                need_odd = m // 2
                need_even = (m + 1) // 2

            if rem_odd != need_odd or rem_even != need_even:
                return 0

            return min(CAP, fact[rem_odd] * fact[rem_even])

        rem_odd = (n + 1) // 2
        rem_even = n // 2

        # For odd n, the first element must be odd.
        # For even n, either parity can start the permutation.
        required_odd = None if n % 2 == 0 else True

        used = [False] * (n + 1)
        ans = []

        for _ in range(n):
            chosen = None

            for x in range(1, n + 1):
                if used[x]:
                    continue

                x_odd = (x % 2 == 1)

                if required_odd is not None and x_odd != required_odd:
                    continue

                if x_odd:
                    if rem_odd == 0:
                        continue
                    block = ways(rem_odd - 1, rem_even, False)
                else:
                    if rem_even == 0:
                        continue
                    block = ways(rem_odd, rem_even - 1, True)

                if block == 0:
                    continue

                if k > block:
                    k -= block
                else:
                    chosen = x
                    break

            if chosen is None:
                return []

            used[chosen] = True
            ans.append(chosen)

            if chosen % 2 == 1:
                rem_odd -= 1
                required_odd = False
            else:
                rem_even -= 1
                required_odd = True

        return ans

from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        C = 4 * side

        def perimeter(p: List[int]) -> int:
            x, y = p
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 2 * side + (side - x)
            return 3 * side + (side - y)

        t = sorted(perimeter(p) for p in points)
        n = len(t)

        if k <= 1:
            return 0
        if k > n:
            return 0

        arr = t + [v + C for v in t]
        m = 2 * n
        steps = range(k - 1)

        def feasible(D: int) -> bool:
            if D == 0:
                return True
            if D * k > C:
                return False

            a = arr
            m_local = m
            nxt = [0] * m_local
            j = 0

            for i in range(m_local):
                if j < i:
                    j = i
                ai = a[i]
                while j < m_local and a[j] - ai < D:
                    j += 1
                nxt[i] = j

            nn = n
            c = C
            nxt_local = nxt

            for start in range(nn):
                idx = start
                limit = start + nn

                for _ in steps:
                    idx = nxt_local[idx]
                    if idx >= limit:
                        break
                else:
                    if a[start] + c - a[idx] >= D:
                        return True

            return False

        lo = 0
        hi = min(side, C // k) + 1

        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                lo = mid + 1
            else:
                hi = mid

        return lo - 1

