import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    A = [x - 1 for x in data[2:2 + N]]

    indeg = [0] * N
    for p in A:
        indeg[p] += 1

    in_cycle = [True] * N
    queue = [i for i in range(N) if indeg[i] == 0]
    head = 0
    while head < len(queue):
        u = queue[head]
        head += 1
        in_cycle[u] = False
        p = A[u]
        indeg[p] -= 1
        if indeg[p] == 0:
            queue.append(p)

    children = [[] for _ in range(N)]
    for c in range(N):
        if not in_cycle[c]:
            children[A[c]].append(c)

    child_count = [0] * N
    for u in range(N):
        if not in_cycle[u]:
            child_count[u] = len(children[u])

    queue = [u for u in range(N) if not in_cycle[u] and child_count[u] == 0]
    head = 0
    order = []
    while head < len(queue):
        u = queue[head]
        head += 1
        order.append(u)
        p = A[u]
        if not in_cycle[p]:
            child_count[p] -= 1
            if child_count[p] == 0:
                queue.append(p)

    seen = [False] * N
    cycle_attached = []
    for i in range(N):
        if in_cycle[i] and not seen[i]:
            cur = i
            attached = []
            while not seen[cur]:
                seen[cur] = True
                attached.extend(children[cur])
                cur = A[cur]
            cycle_attached.append(attached)

    g = [0] * N
    totals = [0] * len(cycle_attached)
    mod = MOD
    cycle_count = len(cycle_attached)

    for _ in range(M):
        for u in order:
            prod = 1
            for c in children[u]:
                prod = (prod * g[c]) % mod
            val = g[u] + prod
            if val >= mod:
                val -= mod
            g[u] = val

        for idx in range(cycle_count):
            prod = 1
            for c in cycle_attached[idx]:
                prod = (prod * g[c]) % mod
            val = totals[idx] + prod
            if val >= mod:
                val -= mod
            totals[idx] = val

    ans = 1
    for t in totals:
        ans = (ans * t) % mod
    print(ans)

if __name__ == "__main__":
    main()

import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    K = data[1]
    A = data[2:2 + N]

    total = 0
    for v in A:
        total ^= v

    choose = K <= N - K
    m = K if choose else N - K

    if m == 0:
        print(total if K == N else 0)
        return

    if m == 1:
        if choose:
            print(max(A))
        else:
            ans = 0
            t = total
            for v in A:
                val = t ^ v
                if val > ans:
                    ans = val
            print(ans)
        return

    base = N - m + 1
    ans = 0

    if choose:
        def dfs(start, x, stop, A=A, N=N):
            nonlocal ans
            if stop == N:
                for i in range(start, N):
                    val = x ^ A[i]
                    if val > ans:
                        ans = val
                return
            for i in range(start, stop):
                dfs(i + 1, x ^ A[i], stop + 1)

        dfs(0, 0, base)
    else:
        def dfs(start, x, stop, A=A, N=N, t=total):
            nonlocal ans
            if stop == N:
                y = t ^ x
                for i in range(start, N):
                    val = y ^ A[i]
                    if val > ans:
                        ans = val
                return
            for i in range(start, stop):
                dfs(i + 1, x ^ A[i], stop + 1)

        dfs(0, 0, base)

    print(ans)

if __name__ == "__main__":
    solve()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        if n == 0:
            return 0

        bits = [1 if ch == '1' else 0 for ch in s]

        max_run = 1
        cur = 1
        for i in range(1, n):
            if bits[i] == bits[i - 1]:
                cur += 1
                if cur > max_run:
                    max_run = cur
            else:
                cur = 1

        INF = numOps + 1

        def feasible(L: int) -> bool:
            dp0 = [INF] * (L + 1)
            dp1 = [INF] * (L + 1)

            first = bits[0]
            dp0[1] = first
            dp1[1] = 1 - first

            for i in range(1, n):
                b = bits[i]

                min0 = min(dp0)
                min1 = min(dp1)
                if min0 == INF and min1 == INF:
                    return False

                c0 = b
                c1 = 1 - b

                ndp0 = [INF] * (L + 1)
                ndp1 = [INF] * (L + 1)

                if min1 < INF:
                    val = min1 + c0
                    ndp0[1] = val if val < INF else INF
                if min0 < INF:
                    val = min0 + c1
                    ndp1[1] = val if val < INF else INF

                if L > 1:
                    if c0 == 0:
                        ndp0[2:] = dp0[1:L]
                    else:
                        ndp0[2:] = [x + 1 if x < INF else INF for x in dp0[1:L]]

                    if c1 == 0:
                        ndp1[2:] = dp1[1:L]
                    else:
                        ndp1[2:] = [x + 1 if x < INF else INF for x in dp1[1:L]]

                dp0, dp1 = ndp0, ndp1

            return min(min(dp0), min(dp1)) <= numOps

        lo, hi = 1, max_run
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo


