    import random

    def brute_force(s: str, numOps: int) -> int:
        n = len(s)
        if n == 0:
            return 0
        best = n
        for mask in range(1 << n):
            dist = 0
            prev = None
            cur = 0
            maxr = 0
            for i in range(n):
                ch = '1' if ((mask >> i) & 1) else '0'
                if ch != s[i]:
                    dist += 1
                    if dist > numOps:
                        break
                if ch == prev:
                    cur += 1
                else:
                    cur = 1
                if cur > maxr:
                    maxr = cur
            else:
                if dist <= numOps and maxr < best:
                    best = maxr
        return best

    sol = Solution()
    failures = []

    examples = [
        ("000001", 1, 2),
        ("0000", 2, 1),
        ("0101", 0, 1),
    ]
    for s, ops, expected in examples:
        got = sol.minLength(s, ops)
        if got != expected:
            failures.append(f"example {s} {ops}: expected {expected}, got {got}")

    edge_cases = [
        ("0", 0),
        ("1", 1),
        ("00000", 0),
        ("00000", 5),
        ("11111", 0),
        ("11111", 1),
        ("11111", 2),
        ("101010", 0),
        ("110011", 1),
        ("0000000000", 0),
        ("0000000000", 1),
        ("0101010101", 0),
    ]
    for s, ops in edge_cases:
        expected = brute_force(s, ops)
        got = sol.minLength(s, ops)
        if got != expected:
            failures.append(f"edge {s} {ops}: expected {expected}, got {got}")

    random.seed(12345)
    for _ in range(100):
        n = random.randint(1, 10)
        s = ''.join(random.choice('01') for _ in range(n))
        ops = random.randint(0, n)
        expected = brute_force(s, ops)
        got = sol.minLength(s, ops)
        if got != expected:
            failures.append(f"random {s} {ops}: expected {expected}, got {got}")

    if failures:
        print("FAIL")
        for msg in failures[:10]:
            print(msg)
    else:
        print("PASS")

from typing import List


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        present = [False] * (threshold + 1)
        isolated = 0
        small_count = 0

        for x in nums:
            if x <= threshold:
                if not present[x]:
                    present[x] = True
                    small_count += 1
            else:
                isolated += 1

        if small_count == 0:
            return isolated

        parent = list(range(threshold + 1))
        size = [1] * (threshold + 1)

        def find(a: int) -> int:
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        first_rep = [0] * (threshold + 1)

        for x in range(1, threshold + 1):
            if not present[x]:
                continue

            root_x = find(x)
            for m in range(x, threshold + 1, x):
                rep = first_rep[m]
                if rep == 0:
                    first_rep[m] = x
                elif rep != x:
                    if rep != root_x:
                        rrep = find(rep)
                        if rrep != root_x:
                            if size[root_x] <= size[rrep]:
                                parent[root_x] = rrep
                                size[rrep] += size[root_x]
                                root_x = rrep
                            else:
                                parent[rrep] = root_x
                                size[root_x] += size[rrep]

        roots = set()
        for x in range(1, threshold + 1):
            if present[x]:
                roots.add(find(x))

        return len(roots) + isolated


