    assert sol.countComponents([1, 2], 1) == 2
    assert sol.countComponents([10, 20, 30], 5) == 3
    assert sol.countComponents([1, 2, 3, 4, 5], 5) == 1
    assert sol.countComponents([4, 6, 12], 12) == 1
